import { AxisScale } from '@visx/axis';
import React from 'react';

import { ThresholdBarTemplate } from './ThresholdBarTemplate.js';
import { THRESHOLD_BAR_THICKNESS } from './types/constants.js';
import { Formatter } from '../../types/formatter.js';

/**
 * @internal
 */
export interface ThresholdMarker {
  id: string;
  color: string;
  y0: number;
  y1: number;
  label?: string;
}

/**
 * @internal
 */
export interface ThresholdBarProps {
  /** Scale of the axis where the threshold bar belongs */
  scale: AxisScale<number>;
  /** Length in absolute pixels for the component.
   * If layout is vertical, this length is used for height.
   * Otherwise, it's used as width.
   */
  length: number;
  /** Markers information to be printed */
  markers: ThresholdMarker[];
  /** If layout should be vertical or horizontal */
  layout: 'vertical' | 'horizontal';
  /** Flips the component considering its current layout.
   * Used to allow the border to be in diferent positions
   * depending on the layout.
   */
  isFlipped?: boolean;
  /**
   * Value formatter that will be used in the threshold markers tooltip.
   */
  formatter?: Formatter;
  /** Callback used when any of the thresholds markers are hovered, the id of the hovered item is passed as an argument. When 'undefined', none item is being hovered */
  onHover?: (id: string | undefined) => void;
}

const ThresholdBarInternal = (props: ThresholdBarProps) => {
  const { length, layout = 'vertical' } = props;

  return layout === 'horizontal' ? (
    /* This is needed to adapt the container to the rotated threshold bar */
    <div
      style={{ width: length, height: THRESHOLD_BAR_THICKNESS }}
      data-testid="threshold-bar-horizontal"
    >
      <ThresholdBarTemplate {...props} />
    </div>
  ) : (
    <div data-testid="threshold-bar-vertical">
      <ThresholdBarTemplate {...props} />
    </div>
  );
};

ThresholdBarInternal['displayName'] = 'ThresholdBarInternal';

/**
 * @internal
 */
export const ThresholdBar = React.memo(ThresholdBarInternal);

ThresholdBar['displayName'] = 'ThresholdBar';
